`default_nettype none
`timescale 1ns/1ps
// Synchronous report background ROM.
// Exact current constant data; eight complete 4096x2 synchronous ROM tables.
// No initial or external image file dependency. One registered bank selector
// preserves the original one-clock result, including 15-bit address wrap.
module recovery_report_background_rom(input wire clk,input wire pacu,input wire [7:0] x,input wire [6:0] y,output wire [1:0] color_index);

wire [13:0] row_address;
wire [14:0] address;
reg [2:0] bank_selector;
wire [1:0] bank_color[0:7];
// Continuous values retain the original net initializer expressions.
assign row_address = ({7'd0,y}<<7)+({7'd0,y}<<4)+({7'd0,y}<<3);
assign address = {1'b0,row_address}+{7'd0,x}+(pacu?15'd0:15'd13376);



always @(posedge clk)bank_selector<=address[14:12];

recovery_report_background_bank_0 bank_0(.clk(clk),.address(address[11:0]),.value(bank_color[0]));
recovery_report_background_bank_1 bank_1(.clk(clk),.address(address[11:0]),.value(bank_color[1]));
recovery_report_background_bank_2 bank_2(.clk(clk),.address(address[11:0]),.value(bank_color[2]));
recovery_report_background_bank_3 bank_3(.clk(clk),.address(address[11:0]),.value(bank_color[3]));
recovery_report_background_bank_4 bank_4(.clk(clk),.address(address[11:0]),.value(bank_color[4]));
recovery_report_background_bank_5 bank_5(.clk(clk),.address(address[11:0]),.value(bank_color[5]));
recovery_report_background_bank_6 bank_6(.clk(clk),.address(address[11:0]),.value(bank_color[6]));
recovery_report_background_bank_7 bank_7(.clk(clk),.address(address[11:0]),.value(bank_color[7]));
assign color_index=bank_color[bank_selector];
endmodule
